{
  "name": "loss_softplus_bpr_rank",
  "intuition": "Bayesian Personalized Ranking style: treat the winner-over-loser log-prob gap as a log-odds score and minimize a smooth hinge (softplus) on the negative score, with an additive rank-difference signal shaping the margin.",
  "pseudocode": "score = alpha*scale*(lpw-lpl) + beta*delta_rank; loss = softplus(-clamp(score, -c, c)); return weighted_mean(loss)",
  "hyperparams": {
    "paradigm_family": "bpr_ranking",
    "signal_family": "delta_rank",
    "link_family": "softplus",
    "agg_family": "weighted_mean",
    "constraint_family": "clamp_stabilized"
  },
  "operators_used": [
    "softplus",
    "clamp"
  ],
  "implementation_hint": {
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "weight",
      "delta_rank"
    ],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    delta_rank = batch['delta_rank']\n\n    hp = extra.get('hyperparams', {}) if isinstance(extra, dict) else {}\n    alpha = float((extra.get('alpha', 1.0) if isinstance(extra, dict) else 1.0))\n    scale = float(hp.get('scale', 1.0))\n    beta = float(hp.get('beta', 0.5))\n    clamp_c = float(hp.get('clamp', 20.0))\n\n    score = alpha * scale * (lpw - lpl) + beta * delta_rank.detach()\n    score = ops.clamp(score, -clamp_c, clamp_c)\n    loss = ops.softplus(-score)\n\n    if weight is not None:\n        loss = loss * weight\n        denom = ops.clamp(weight.sum(), 1e-12, 1e30)\n        return loss.sum() / denom\n    return loss.mean()\"\n}

{
  "name": "loss_logsigmoid_000_cost_tuned_scale_2435_m3_expects_fix",
  "intuition": "Fix the static gate failure by adding a concrete, non-empty `implementation_hint.expects` list of required batch keys. Keep the original, stable pairwise `-logsigmoid` form, but make weighting numerically safer by clamping weights to be non-negative (per builder constraint) and normalizing by mean weight (with epsilon) instead of a plain mean; this avoids loss-scale blowups when weights are large or sparse while preserving preference semantics.",
  "pseudocode": "x = clamp(alpha*scale*(lpw-lpl) - 0.1*detach(cost_b-cost_a), -20, 20); loss = -logsigmoid(x); if weight: w=clamp(weight,0,inf); return sum(w*loss)/(sum(w)+eps) else mean(loss)",
  "hyperparams": {
    "scale": 2.435921118612359,
    "paradigm_family": "pairwise_margin",
    "signal_family": "cost_gap",
    "link_family": "logsigmoid",
    "agg_family": "weighted_mean",
    "constraint_family": "clamp_stabilized"
  },
  "operators_used": [
    "logsigmoid",
    "clamp"
  ],
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    cost_a = batch['cost_a']\n    cost_b = batch['cost_b']\n\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 2.435921118612359))\n\n    gap = (cost_b - cost_a).detach()\n    x = alpha * scale * (lpw - lpl) - 0.1 * gap\n    x = ops.clamp(x, -20.0, 20.0)\n    per_ex_loss = -ops.logsigmoid(x)\n\n    weight = batch.get('weight', None)\n    if weight is None:\n        return per_ex_loss.mean()\n\n    w = ops.clamp(weight, 0.0, 1e9)\n    num = (per_ex_loss * w).sum()\n    denom = w.sum() + 1e-8\n    return num / denom",
  "theoretical_basis": "",
  "implementation_hint": {
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "cost_a",
      "cost_b"
    ],
    "optional": [
      "weight"
    ]
  }
}

{
  "name": "loss_pairwise_mse_regret_delta",
  "intuition": "Shift from margin-classification (logsigmoid) to regression-on-signal: directly fit the model's log-prob gap to a target preference strength (delta_regret). This treats pairwise supervision as a calibrated scalar target rather than a binary win/loss, using a smooth L2 objective that can encode varying preference intensity.",
  "pseudocode": "pred = clamp(alpha*scale*(lpw-lpl), -clip, clip)\nloss_i = 0.5 * (pred - beta*delta_regret)^2\nloss = weighted_mean(loss_i)",
  "hyperparams": {
    "paradigm_family": "pairwise_regression",
    "signal_family": "delta_regret",
    "link_family": "identity",
    "agg_family": "weighted_mean",
    "constraint_family": "clamp_stabilized"
  },
  "operators_used": [
    "clamp"
  ],
  "implementation_hint": {
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "weight",
      "delta_regret"
    ],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    delta_regret = batch['delta_regret']\n\n    hp = extra.get('hyperparams', {}) if isinstance(extra, dict) else {}\n    alpha = float(extra.get('alpha', hp.get('alpha', 1.0))) if isinstance(extra, dict) else 1.0\n    scale = float(hp.get('scale', 1.0))\n    beta = float(hp.get('beta', 1.0))\n    clip = float(hp.get('clip', 20.0))\n\n    pred = alpha * scale * (lpw - lpl)\n    pred = ops.clamp(pred, -clip, clip)\n    target = (beta * delta_regret).detach()\n\n    per_pair = 0.5 * (pred - target) * (pred - target)\n\n    if weight is not None:\n        denom = ops.clamp(weight.sum(), 1e-12, 1e12)\n        return (per_pair * weight).sum() / denom\n    return per_pair.mean()"
}

{
  "name": "loss_softplus_regret_tempered_gapcenter",
  "intuition": "Novelty repair: the prior candidate matched an existing regret-scaled softplus margin almost exactly (same detached delta_regret->sigmoid scale->clamp->softplus pipeline and weighted normalization). I changed the functional form while keeping the same inputs: (1) replace bounded sigmoid scaling with a detached, gap-centered temperature that *divides* the margin (tempering) instead of multiplying it; (2) make the temperature depend on how far delta_regret is from its batch mean, using a smooth absolute value via sqrt(x^2+tau^2); (3) use an offset margin (beta) and an effective weight that downweights high-temperature (less reliable) pairs. This keeps everything vectorized, uses only ops/tensor math, returns a scalar tensor, and should reduce similarity while preserving the regret-reliability idea.",
  "pseudocode": "g = lpw - lpl\nr = detach(delta_regret)\nrc = r - mean(r)\nad = sqrt(rc^2 + tau^2)\nT = 1 + temp_scale * ad\nz = (alpha*g - beta) / T\nper = softplus(-z)\nw_eff = weight / T\nL = sum(w_eff*per) / (sum(w_eff) + eps)",
  "hyperparams": {
    "paradigm_family": "regret_tempered_margin",
    "signal_family": "delta_regret_centered_detached",
    "link_family": "softplus_tempered",
    "agg_family": "weighted_sum_normalized",
    "constraint_family": "temperature_lower_bounded",
    "other_hparams": "Temperature is 1+temp_scale*sqrt((r-mean(r))^2+tau^2) with r detached; margin is divided by temperature (tempering) and weights are also tempered by 1/T to reduce influence of uncertain pairs."
  },
  "operators_used": [
    "softplus",
    "sqrt"
  ],
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch['weight']\n    delta_regret = batch['delta_regret']\n\n    hp = extra.get('hyperparams', {})\n    alpha = float(extra.get('alpha', hp.get('alpha', 1.0)))\n    beta = float(hp.get('beta', 0.0))\n    temp_scale = float(hp.get('temp_scale', 1.0))\n    tau = float(hp.get('tau', 1e-3))\n    eps = float(hp.get('eps', 1e-8))\n\n    gap = lpw - lpl\n\n    # Detached, batch-centered regret; temperature grows with |r - mean(r)|.\n    r = delta_regret.detach()\n    rc = r - r.mean()\n    ad = ops.sqrt(rc * rc + (tau * tau))\n    T = 1.0 + temp_scale * ad\n\n    z = (alpha * gap - beta) / T\n    per_pair = ops.softplus(-z)\n\n    w_eff = weight / T\n    num = (w_eff * per_pair).sum()\n    den = w_eff.sum() + eps\n    return num / den",
  "theoretical_basis": "",
  "implementation_hint": {
    "expects": {
      "batch": {
        "log_prob_w": "Tensor[batch]",
        "log_prob_l": "Tensor[batch]",
        "weight": "Tensor[batch]",
        "delta_regret": "Tensor[batch]"
      },
      "model_output": "unused",
      "extra": {
        "alpha": "float (optional)",
        "hyperparams": {
          "alpha": "float (optional)",
          "beta": "float (optional)",
          "temp_scale": "float (optional)",
          "tau": "float (optional)",
          "eps": "float (optional)"
        }
      }
    },
    "mode": "pairwise_preference"
  }
}

{
  "name": "builder_all_pairs_tieclamp_001",
  "intuition": "All-pairs pairing with an explicit tie-zone constraint: filter out near-equal objectives (ties) and clamp objectives to avoid NaN/inf-driven invalid comparisons, preserving pairwise PrefBatch output.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "uniform_none",
    "constraint_family": "tie_zone_filter_objective_clamp"
  },
  "operators_used": [
    "all_pairs",
    "clamp",
    "abs",
    "tie_zone_filter"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n\n    hp = extra.get('hyperparams', {})\n    # tie_eps filters out near-ties where supervision is ambiguous.\n    tie_eps = float(extra.get('tie_eps', hp.get('tie_eps', 0.0)))\n    # obj_clip prevents inf/nan propagation in comparisons.\n    obj_clip = float(extra.get('obj_clip', hp.get('obj_clip', 1e6)))\n\n    obj = ops.clamp(objective, -obj_clip, obj_clip)\n\n    # Prefer lower objective values; create all winner/loser pairs.\n    diff = obj[:, :, None] - obj[:, None, :]\n    strict = diff < 0\n\n    # Explicit constraint: remove tie/near-tie zone.\n    if tie_eps > 0.0:\n        strict = strict & (ops.abs(diff) > tie_eps)\n\n    b_idx, winner_idx, loser_idx = strict.nonzero(as_tuple=True)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs_tieclamp', 'tie_eps': tie_eps, 'obj_clip': obj_clip})\n"
}

{
