  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n\n    hp = extra.get('hyperparams', {})\n    tie_eps = float(hp.get('tie_eps', 1e-6))\n    obj_clip = float(hp.get('obj_clip', 1e9))\n\n    # Constraint handling: clamp extreme objective values and filter out near-ties.\n    obj = ops.clamp(objective, -obj_clip, obj_clip)\n\n    # Build all winner/loser pairs (lower objective is better).\n    diff = obj[:, :, None] - obj[:, None, :]\n    mask = diff < (-tie_eps)\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs_tie_zone_clamp', 'tie_eps': tie_eps, 'obj_clip': obj_clip})\n"
}

{
  "name": "builder_sampled_pairs_gapthr_topk_002",
  "intuition": "Select only confidently better (lower objective) winners by enforcing a configurable positive gap threshold, then cap the total budget by keeping the largest gaps via topk so training focuses on the clearest improvements.",
  "hyperparams": {
    "geometry_family": "sampled_pairs_gap_threshold",
    "cap_family": "topk_budget",
    "weight_family": "uniform_none",
    "constraint_family": "gap_threshold_clamp"
  },
  "operators_used": [
    "broadcast_sub",
    "gt_mask",
    "nonzero",
    "topk"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    hp = extra.get('hyperparams', {})\n\n    # lower objective is better: winner has strictly lower objective than loser\n    gap_thr = float(extra.get('gap_threshold', hp.get('gap_threshold', 1e-6)))\n    max_pairs = int(extra.get('max_pairs', hp.get('max_pairs', 256)))\n\n    # gap[b,i,j] = obj[b,j] - obj[b,i] is positive when i is better than j\n    gap = objective[:, None, :] - objective[:, :, None]\n    mask = gap > gap_thr\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n\n    if b_idx.numel() > max_pairs:\n        scores = gap[b_idx, winner_idx, loser_idx]\n        keep = torch.topk(scores, k=max_pairs, largest=True, sorted=False).indices\n        b_idx = b_idx[keep]\n        winner_idx = winner_idx[keep]\n        loser_idx = loser_idx[keep]\n\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'sampled_pairs_gapthr_topk', 'gap_threshold': gap_thr, 'max_pairs': max_pairs})\n"
}

